511456vyzLN 441149afowzN 8218mnGH 1414afwyzHN 7211 441kxJ 111mrtE 2015R 451tH 411rwCH 8212bewDEN
';
  want_cohort constant text := '81b63f0922ec2054a862b762c538b315';
  want_labs   constant text := '810bf4bb7d7f68b173f5f053387a8364';
  got         text;
begin
  -- Guard: 018 must be applied AND live. Re-running the whole 005 keeps 018's _applied row but puts 005's
  -- slow body back (CTO, measured), so the live function body is checked as well as _applied.
  if not exists (select 1 from __SCHEMA__._applied where file = '018_matches_codes_once.sql') then
    raise exception '019_seed_match_cohort_5000.sql needs 018_matches_codes_once.sql: apply 018 first';
  end if;
  if not exists (select 1 from pg_proc p
                 where p.oid = to_regprocedure('__SCHEMA__.healthapp_possible_matches(uuid)')
                   and p.prosrc like '%into my_codes%') then
    raise exception '019_seed_match_cohort_5000.sql: 018''s healthapp_possible_matches is not live (005 re-run?): apply 018 again';
  end if;

  -- Lab thresholds, from match.LAB_DEFS (marker -> analyte_key of the extraction): the same values as 006.
  insert into __SCHEMA__.match_lab_defs (analyte_key, unit, ref_low, ref_high, code_above, code_below) values
    ('ace', 'U/L', 8, 52, 'ACE_high', null),
    ('alt', 'U/L', 7, 40, 'ALT_high', null),
    ('ana', 'qual', 0, 0, 'ANA_positive', null),
    ('anti_ccp', 'U/mL', 0, 20, 'anti_CCP_positive', null),
    ('ceruloplasmin', 'mg/dL', 20, 60, null, 'ceruloplasmin_low'),
    ('ck', 'U/L', 30, 200, 'CK_high', null),
    ('creatinine', 'mg/dL', 0.6, 1.3, 'creatinine_high', null),
    ('crp', 'mg/L', 0, 5, 'CRP_high', null),
    ('esr', 'mm/h', 0, 20, 'ESR_high', null),
    ('ferritin', 'ng/mL', 30, 300, null, 'ferritin_low'),
    ('hba1c', '%', 4.0, 5.6, 'HbA1c_high', null),
    ('hemoglobin', 'g/dL', 12.0, 17.5, null, 'Hb_low'),
    ('hla_b27', 'qual', 0, 0, 'HLA_B27_positive', null),
    ('ldl', 'mg/dL', 0, 130, 'LDL_high', null),
    ('rf', 'IU/mL', 0, 14, 'RF_positive', null),
    ('tsh', 'mIU/L', 0.4, 4.0, 'TSH_high', 'TSH_low'),
    ('uric_acid', 'mg/dL', 3.5, 7.2, 'uric_acid_high', null),
    ('vitamin_d', 'ng/mL', 30, 100, null, 'vitD_low'),
    ('wbc', '10^9/L', 4.0, 11.0, 'WBC_high', 'WBC_low')
  on conflict (analyte_key) do update set unit = excluded.unit, ref_low = excluded.ref_low,
    ref_high = excluded.ref_high, code_above = excluded.code_above, code_below = excluded.code_below;
  delete from __SCHEMA__.match_lab_defs where analyte_key <> all (array[
    'ace','alt','ana','anti_ccp','ceruloplasmin','ck','creatinine','crp','esr','ferritin','hba1c','hemoglobin',
    'hla_b27','ldl','rf','tsh','uric_acid','vitamin_d','wbc']);

  -- The 5,000 rows: word n is upserted as syn-n, then every row outside syn-0001..syn-5000 is deleted.
  insert into __SCHEMA__.match_cohort (id, country, age_band, matching_opt_in, codes)
  select 'syn-' || lpad(w.n::text, 4, '0'),
         v_countries[strpos(b62, substr(w.word, 1, 1))],
         v_bands[strpos(b62, substr(w.word, 2, 1))],
         substr(w.word, 3, 1) = '1',
         array(select v_codes[strpos(b62, x.ch)]
               from unnest(string_to_array(substr(w.word, 4), null)) with ordinality x (ch, i) order by x.i)
  from unnest(regexp_split_to_array(btrim(v_payload, E' \n'), '\s+')) with ordinality w (word, n)
  on conflict (id) do update set country = excluded.country, age_band = excluded.age_band,
    matching_opt_in = excluded.matching_opt_in, codes = excluded.codes;
  delete from __SCHEMA__.match_cohort where id collate "C" not between 'syn-0001' and 'syn-5000';

  -- Self-check before anything commits: the cohort as `scripts/hdb matches` fingerprints it, then the thresholds.
  select md5(string_agg(id || ' ' || country || ' ' || age_band || ' ' || matching_opt_in::text || ' '
                        || array_to_string(codes, ','), '|' order by id collate "C"))
    into got from __SCHEMA__.match_cohort;
  if got is distinct from want_cohort then
    raise exception '019_seed_match_cohort_5000.sql: cohort fingerprint % is not %: nothing was changed',
      got, want_cohort;
  end if;
  select md5(string_agg(analyte_key || ' ' || unit || ' ' || ref_low::text || ' ' || ref_high::text || ' '
                        || coalesce(code_above, '') || ' ' || coalesce(code_below, ''),
                        '|' order by analyte_key collate "C"))
    into got from __SCHEMA__.match_lab_defs;
  if got is distinct from want_labs then
    raise exception '019_seed_match_cohort_5000.sql: lab thresholds fingerprint % is not %: nothing was changed',
      got, want_labs;
  end if;
  insert into __SCHEMA__._applied (file) values ('019_seed_match_cohort_5000.sql') on conflict (file) do nothing;
end $$;
